 public static function text($value,int $min=0,int $max=500): string {if(!is_scalar($value))throw new \InvalidArgumentException('متن معتبر نیست.');$value=trim(strip_tags((string)$value));if(mb_strlen($value)<$min||mb_strlen($value)>$max)throw new \InvalidArgumentException('طول متن معتبر نیست.');return $value;}
