 public static function settings(): array {$raw=get_option(self::SETTINGS,[]);$raw=is_array($raw)?$raw:[];return array_merge(['over_pct'=>5,'expiry_warning_days'=>30,'retention_days'=>730,'receipt_cap'=>500,'line_cap'=>100,'event_cap'=>800,'minimum_score_sample'=>3,'defects'=>self::DEFECTS],$raw);}
