 public static function purchaseSummary(string $purchaseId,?array $receipts=null): array {$p=self::purchases()[$purchaseId]??null;if(!$p)throw new \RuntimeException('سفارش خرید وجود ندارد.');$out=[];foreach($p['lines'] as $material=>$line)$out[$material]=['ordered'=>(float)$line['qty'],'counted'=>0.0,'accepted'=>0.0,'quarantined'=>0.0,'rejected'=>0.0,'remaining'=>(float)$line['qty']];foreach($receipts??self::receipts() as $receipt)if($receipt['purchase_id']===$purchaseId&&!in_array($receipt['state'],['cancelled'],true))foreach($receipt['lines'] as $material=>$line){if(!isset($out[$material]))continue;$out[$material]['counted']+=(float)($line['counted']??0);foreach(['accepted','quarantined','rejected'] as $field)$out[$material][$field]+=(float)($line[$field]??0);$out[$material]['remaining']=max(0,$out[$material]['ordered']-$out[$material]['accepted']-$out[$material]['rejected']);}return $out;}
