lines'=>$lines,'history'=>[],'posted'=>false];self::event($r,'create',['materials'=>array_keys($lines)]);self::save($all,$r);return $r;}
 public static function supplierId(string $name): string {$normalized=mb_strtolower(trim(preg_replace('/\s+/u',' ',$name)));$canonical=self::supplierAliases()[$normalized]??$normalized;$normalized=mb_strtolower(trim(preg_replace('/\s+/u',' ',$canonical)));return 'supplier-'.substr(hash('sha256',$normalized),0,16);}
