 public static function transitionPurchase(string $id,int $revision,string $to,string $reason=''): array {if(!self::canManage())throw new \RuntimeException('مدیریت خرید مجاز نیست.');$all=self::purchases();$p=$all[$id]??null;if(!$p||$p['revision']!==$revision)throw new \RuntimeException('خرید یا نسخه آن معتبر نیست.');$allowed=['draft'=>['ordered','cancelled'],'ordered'=>['partially_received','cancelled'],'partially_received'=>['received','cancelled'],'received'=>[],'cancelled'=>[]];if(!in_array($to,$allowed[$p['status']]??[],true))throw new \RuntimeException('گذار وضعیت خرید مجاز نیست.');if($to==='cancelled')$p['cancel_reason']=self::text($reason,3,500);$p['status']=$to;$p['revision']++;$p['updated_at']=self::now();$all[$id]=$p;if(!update_option(self::PURCHASES,$all,false))throw new \RuntimeException('ذخیره وضعیت خرید ناموفق بود.');return $p;}
 public static function countLine(string $id,int $revision,string $material,int $lineRevision,array $p): array {$all=self::receipts();$r=$all[self::receiptId($id)]??null;if(!$r||$r['revision']!==$revision||!self::canCount())throw new \RuntimeException('رسید، نسخه یا مجوز معتبر نیست.');if(!in_array($r['state'],['awaiting_count','inspecting'],true))throw new \RuntimeException('رسید در مرحله شمارش نیست.');$material=self::key($material);$line=$r['lines'][$material]??null;if(!$line||$line['revision']!==$lineRevision)throw new \RuntimeException('ردیف یا نسخه آن معتبر نیست.');if(empty($p['human']))throw new \InvalidArgumentException('تأیید مشاهده و شمارش دستی لازم است.');$counted=self::quantity($p['counted']??null,$line['precision']);$damaged=self::quantity($p['damaged']??0,$line['precision']);if($damaged>$counted)throw new \InvalidArgumentException('آسیب از شمارش بیشتر است.');$observation=self::text($p['observation']??'',($damaged>0?3:0),1000);$lot=self::lot((string)($p['lot']??''));$expires=self::expiry($p['expiry']??'',!empty($p['no_expiry']),self::now());$defects=[];$critical=false;foreach(array_unique((array)($p['defects']??[])) as $code){$code=strtolower(self::key($code));$d=self::defects()[$code]??null;if(!$d||!$d['active'])throw new \InvalidArgumentException('کد عیب فعال نیست.');$defects[$code]=$d;if($d['severity']==='critical')$critical=true;}if(($damaged>0||$defects)&&$observation==='')throw new \InvalidArgumentException('شرح مشاهده برای آسیب لازم است.');$summary=self::purchaseSummary($r['purchase_id'],$all);$remaining=$summary[$material]['remaining']+$line['accepted']+$line['rejected'];$max=$remaining*(1+$r['thresholds']['over_pct']/100);if($counted>$remaining){if(!self::canManage()||$counted>$max||self::text($p['over_reason']??'',3,500)==='')throw new \RuntimeException('اضافه‌تحویل مجاز یا مستدل نیست.');}$snapshot=['id'=>bin2hex(random_bytes(8)),'counted'=>$counted,'damaged'=>$damaged,'healthy'=>$counted-$damaged,'lot'=>$lot,'expiry'=>$expires,'no_expiry'=>!emp