 public static function decide(string $id,int $revision,string $material,int $lineRevision,array $p): array {$all=self::receipts();$r=$all[self::receiptId($id)]??null;if(!$r||$r['revision']!==$revision||!self::canDecide())throw new \RuntimeException('رسید، نسخه یا مجوز معتبر نیست.');if($r['state']!=='inspecting')throw new \RuntimeException('رسید در مرحله تصمیم نیست.');$material=self::key($material);$line=$r['lines'][$material]??null;if(!$line||$line['revision']!==$lineRevision||!$line['counts'])throw new \RuntimeException('ردیف شمارش‌شده معتبر نیست.');$accepted=self::quantity($p['accepted']??0,$line['precision']);$quarantine=self::quantity($p['quarantined']??0,$line['precision']);$rejected=self::quantity($p['rejected']??0,$line['precision']);if(abs($accepted+$quarantine+$rejected-$line['counted'])>pow(10,-$line['precision'])/2)throw new \InvalidArgumentException('جمع تصمیم‌ها باید برابر شمارش باشد.');$critical=false;foreach($line['defects'] as $d)if($d['severity']==='critical')$critical=true;if($critical&&$quarantine<=0)throw new \RuntimeException('نقص بحرانی نیازمند قرنطینه است.');if($line['damaged']>0&&$quarantine+$rejected<$line['damaged'])throw new \RuntimeException('مقدار آسیب‌دیده باید قرنطینه یا رد شود.');$reason=self::text($p['reason']??'',($quarantine>0||$rejected>0?3:0),500);$decision=['accepted'=>$accepted,'quarantined'=>$quarantine,'rejected'=>$rejected,'reason'=>$reason,'actor'=>get_current_user_id(),'at'=>self::now(),'released_by'=>0];$line['accepted']=$accepted;$line['quarantined']=$quarantine;$line['rejected']=$rejected;$line['decision']=$decision;$line['revision']++;$r['lines'][$material]=$line;$r['state']=self::deriveState($r);$r['revision']++;self::event($r,'decide',['material'=>$material]+$decision);self::save($all,$r);return $r;}
 public static function deriveState(array $r): string {$pending=false;$q=0.0;$accepted=0.0;$rejected=0.0;foreach($r['lines'] as $line){if(!$line['decision'])$pending=true;$q+=$line['quarantined'];$accepted+=$line['accepted'];$rejected+=$line['rejected'];}if($pending)return 'inspecting';if($q>0)return 'quarantined';if($accepted>0)return 'accepted';return $rejected>0?'rejected':'inspecting';}
