 public static function post(string $id,int $revision): array {$all=self::receipts();$r=$all[self::receiptId($id)]??null;if(!$r||!self::canDecide())throw new \RuntimeException('ثبت موجودی مجاز نیست.');if($r['revision']!==$revision&&!$r['posted'])throw new \RuntimeException('نسخه رسید تغییر کرده است.');if($r['state']==='quarantined'||$r['state']==='inspecting'||$r['state']==='awaiting_count')throw new \RuntimeException('همه ردیف‌ها باید تعیین تکلیف شوند.');$stock=self::stock();$markers=is_array($stock['__v37_receipts']??null)?$stock['__v37_receipts']:[];$totals=[];foreach($r['lines'] as $material=>$line)if($line['accepted']>0)$totals[$material]=($totals[$material]??0)+$line['accepted'];if(!isset($markers[$id])){$next=$stock;foreach($totals as $material=>$qty){if(!isset($next[$material])||!is_array($next[$material]))throw new \RuntimeException('ماده در موجودی وجود ندارد: '.$material);$next[$material]['stock']=(float)($next[$material]['stock']??0)+$qty;$lotKey=$material.'|'.$r['lines'][$material]['lot'];$next['__v37_lots'][$lotKey]=['material'=>$material,'lot'=>$r['lines'][$material]['lot'],'expiry'=>$r['lines'][$material]['expiry'],'available'=>$qty,'receipt_id'=>$id,'received_at'=>$r['created_at']];}$next['__v37_receipts']=$markers;$next['__v37_receipts'][$id]=['totals'=>$totals,'at'=>self::now(),'actor'=>get_current_user_id()];if(!update_option(self::STOCK,$next,false))throw new \RuntimeException('افزایش موجودی ذخیره نشد.');}$r['posted']=true;$r['posted_at']=$stock['__v37_receipts'][$id]['at']??self::now();$r['posted_actor']=get_current_user_id();$r['revision']++;self::event($r,'post',['totals'=>$totals]);self::save($all,$r);self::syncPurchase($r,$all);return $r;}
 private static function syncPurchase(array $r,array $receipts): void {$orders=self::purchases();$p=$orders[$r['purchase_id']]??null;if(!$p)return;$summary=self::purchaseSummary($r['purchase_id'],$receipts);$complete=true;$any=false;foreach($summary as $row){if($row['accepted']+$row['rejected']>0)$any=true;if($row['remaining']>0)$complete=false;}$p['status']=$complete?'received':($any?'partially_received':'ordered');$p['revision']++;$p['updated_at']=self::now();$orders[$p['id']]=$p;update_option(self::PURCHASES,$orders,false);}
 public static function move(string $id,int $revision,string $lane): array {$all=self::receipts();$r=$all[self::receiptId($id)]??null;if(!$r||$r['revision']!==$revision||!self::canCount())throw new \RuntimeException('انتقال مجاز نیست.');if(!in_array($lane,self::LANES,true))throw new \InvalidArgumentException('ستون معتبر نیست.');$allowed=['awaiting_count'=>['inspecting'],'inspecting'=>['awaiting_count'],'quarantined'=>[],'accepted'=>[],'rejected'=>[]];if(!in_array($lane,$allowed[$r['state']]??[],true))throw new \RuntimeException('گذار برد مجاز نیست.');$r['state']=$lane;$r['revision']++;self::event($r,'move',['lane'=>$lane]);self::save($all,$r);return $r;}
 public static function score(string $supplierId): array {$final=[];foreach(self::receipts() as $r)if($r['supplier_id']===$supplierId&&$r['posted'])$final[]=$r;$n=count($final);$counted=$accepted=$quarantine=$over=$delay=0.0;foreach($final as $r){$delay+=max(0,(strtotime($r['created_at'])-strtotime($r['purchase_snapshot']['created_at']))/86400);foreach($r['lines'] as $line){$counted+=$line['counted'];$accepted+=$line['accepted'];$quarantine+=$line['quarantined'];if(($line['counts'][count($line['counts'])-1]['over_reason']??'')!=='')$over++;}}return ['sample'=>$n,'insufficient'=>$n<(int)self::settings()['minimum_score_sample'],'healthy_pct'=>$counted?round(100*$accepted/$counted,2):0,'quarantine_pct'=>$counted?round(100*$quarantine/$counted,2):0,'over_receipts'=>$over,'average_recorded_delay_days'=>$n?round($delay/$n,2):0,'descriptive_only'=>true,'causality_claimed'=>false];}
 public static function lotsForUse(string $material): array {$today=gmdate('Y-m-d');$rows=[];foreach((array)(self::stock()['__v37_lots']??[]) as $row)if($row['material']===$material&&$row['available']>0&&($row['expiry']===null||$row['expiry']>=$today))$rows[]=$row;usort($rows,static fn($a,$b)=>strcmp($a['expiry']??'9999-12-31',$b['expiry']??'9999-12-31')?:strcmp($a['received_at'],$b['received_at']));return $rows;}
 public static function csv(array $rows): string {$out="receipt_id,purchase_id,material,lot,counted,accepted,quarantined,rejected,state\r\n";foreach($rows as $r)foreach($r['lines'] as $line){$cells=[$r['id'],$r['purchase_id'],$line['material'],$line['lot'],$line['counted'],$line['accepted'],$line['quarantined'],$line['rejected'],$r['state']];$cells=array_map(static function($v){$v=(string)$v;if(preg_match('/^[=+\-@]/',$v))$v="'".$v;return '"'.str_replace('"','""',$v).'"';},$cells);$out.=implode(',',$cells)."\r\n";}return $out;}
 public static function privacyForUser(int $user): array {$out=[];foreach(self::receipts() as $r){$events=array_values(array_filter($r['history'],static fn($e)=>(int)$e['actor']===$user));$lines=[];foreach($r['lines'] as $line){$counts=array_values(array_filter($line['counts'],static fn($e)=>(int)$e['actor']===$user));if($counts||((int)($line['decision']['actor']??0)===$user)||(int)($line['decision']['released_by']??0)===$user)$lines[$line['material']]=['counts'=>$counts,'decision'=>$line['decision']];}if($events||$lines||(int)$r['actor']===$user||(int)($r['posted_actor']??0)===$user)$out[]=['receipt_id'=>$r['id'],'events'=>$events,'lines'=>$lines];}return $out;}
 public static function eraseUser(int $user): int {$all=self::receipts();$changed=0;foreach($all as &$r){foreach(['actor','posted_actor'] as $field)if((int)($r[$field]??0)===$user){$r[$field]=0;$changed++;}foreach($r['history'] as &$e){if((int)$e['actor']===$user){$e['actor']=0;$changed++;}if((int)($e['detail']['actor']??0)===$user){$e['detail']['actor']=0;$changed++;}if((int)($e['detail']['released_by']??0)===$user){$e['detail']['released_by']=0;$changed++;}}unset($e);foreach($r['lines'] as &$line){foreach($line['counts'] as &$c)if((int)$c['actor']===$user){$c['actor']=0;$changed++;}unset($c);foreach(['actor','released_by'] as $field)if((int)($line['decision'][$field]??0)===$user){$line['decision'][$field]=0;$changed++;}}unset($line);}unset($r);if($changed&&!update_option(self::RECEIPTS,$all,false))throw new \RuntimeException('ناشناس‌سازی ناموفق بود.');return $changed;}
 public static function purge(int $days,bool $dryRun=true): array {$cut=time()-max(30,$days)*86400;$ids=[];foreach(self::receipts() as $id=>$r)if($r['posted']&&strtotime($r['updated_at'])<$cut)$ids[]=$id;if(!$dryRun&&$ids){$all=self::receipts();foreach($ids as $id)unset($all[$id]);update_option(self::RECEIPTS,$all,false);}return ['dry_run'=>$dryRun,'ids'=>$ids,'count'=>count($ids)];}
 public static function ajax(): void {if(!check_ajax_referer(self::NONCE,'nonce',false))wp_send_json_error(['message'=>'درخواست نامعتبر است.'],403);$p=isset($_POST['payload'])&&is_string($_POST['payload'])?json_decode(wp_unslash($_POST['payload']),true):null;if(!is_array($p))wp_send_json_error(['message'=>'داده نامعتبر است.'],400);try{$intent=(string)($p['intent']??'');if($intent==='create')$r=self::create((string)$p['purchase_id'],(int)$p['purchase_revision'],(string)$p['token'],(array)$p['materials']);elseif($intent==='count')$r=self::countLine((string)$p['id'],(int)$p['revision'],(string)$p['material'],(int)$p['line_revision'],(array)($p['data']??[]));elseif($intent==='decide')$r=self::decide((string)$p['id'],(int)$p['revision'],(string)$p['material'],(int)$p['line_revision'],(array)($p['data']??[]));elseif($intent==='release')$r=self::release((string)$p['id'],(int)$p['revision'],(string)$p['material'],!empty($p['accept']),(string)($p['reason']??''));elseif($intent==='move')$r=self::move((string)$p['id'],(int)$p['revision'],(string)$p['lane']);elseif($intent==='post')$r=self::post((string)$p['id'],(int)$p['revision']);else throw new \InvalidArgumentException('عملیات رابط معتبر نیست.');wp_send_json_success(['receipt'=>$r]);}catch(\Throwable $e){wp_send_json_error(['message'=>$e->getMessage()],409);}}
 public static function download(): void {if(!self::canView()||!check_admin_referer(self::NONCE))wp_die('دسترسی مجاز نیست.');nocache_headers();header('Content-Type: text/csv; charset=UTF-8');header('Content-Disposition: attachment; filename=mahex-supply-receipts.csv');echo "\xEF\xBB\xBF".self::csv(self::receipts());exit;}
 public static function printSheet(): void {if(!self::canView()||!check_admin_referer(self::NONCE))wp_die('دسترسی مجاز نیست.');$id=self::receiptId((string)($_GET['receipt']??''));$r=self::receipts()[$id]??null;if(!$r)wp_die('رسید وجود ندارد.');echo '<!doctype html><html dir="rtl"><meta charset="utf-8"><title>برگه دریافت</title><style>body{font-family:tahoma;max-width:900px;margin:auto}table{width:100%;border-collapse:collapse}td,th{border:1px solid #555;padding:8px}</style><h1>برگه دریافت آفلاین '.esc_html($r['code']).'</h1><p>این برگه تا ورود دستی در سامانه نهایی نیست.</p><table><tr><th>ماده</th><th>lot</th><th>شمارش</th><th>امضا</th></tr>';foreach($r['lines'] as $line)echo '<tr><td>'.esc_html($line['name']).'</td><td>'.esc_html($line['lot']).'</td><td></td><td></td></tr>';echo '</table></html>';exit;}
 public static function page(): void {if(!self::canView())wp_die('دسترسی مجاز نیست.');$rows=self::receipts();$counts=array_fill_keys(self::LANES,0);foreach($rows as $r)$counts[$r['state']]++;echo '<div class="wrap hmr-v37" dir="rtl"><h1>دریافت مرحله‌ای ملزومات بسته‌بندی</h1><p class="notice notice-info">همه شمارش‌ها و تصمیم‌ها ثبت دستی کاربر مجازند؛ هیچ API ماهکس، اتصال تأمین‌کننده، دستگاه یا تأیید بیرونی وجود ندارد.</p><nav><a class="button" href="'.esc_url(wp_nonce_url(add_query_arg(['action'=>'hm_mahex_v37_receiving_csv'],admin_url('admin-post.php')),self::NONCE)).'">CSV کم‌داده</a></nav><div class="hmr-filter"><label>جست‌وجو <input type="search" data-hmr-search></label><label>وضعیت <select data-hmr-state><option value="">همه</option>';foreach(self::LANES as $lane)echo '<option value="'.$lane.'">'.$lane.'</option>';echo '</select></label></div><p data-hmr-live aria-live="polite"></p><div class="hmr-board">';foreach(self::LANES as $lane){echo '<section class="hmr-lane" data-lane="'.$lane.'"><h2>'.$lane.' <span>'.$counts[$lane].'</span></h2><div class="hmr-drop" data-drop="'.$lane.'">';foreach($rows as $r)if($r['state']===$lane){echo '<article class="hmr-card" draggable="true" tabindex="0" data-id="'.$r['id'].'" data-revision="'.$r['revision'].'" data-state="'.$lane.'" data-search="'.esc_attr($r['code'].' '.$r['purchase_id'].' '.$r['supplier'].' '.implode(' ',array_keys($r['lines']))).'"><b>'.esc_html($r['code']).'</b><small>'.esc_html($r['supplier']).'</small><label>انتقال با صفحه‌کلید <select data-hmr-move><option value="">انتخاب</option>';foreach(self::LANES as $to)echo '<option value="'.$to.'">'.$to.'</option>';echo '</select></label><a target="_blank" href="'.esc_url(wp_nonce_url(add_query_arg(['action'=>'hm_mahex_v37_receiving_print','receipt'=>$r['id']],admin_url('admin-post.php')),self::NONCE)).'">چاپ آفلاین</a></article>';}echo '</div></section>';}echo '</div></div>';}
}
